@layer components {
  :where([data-control-family="table-of-contents"][data-slot="root"]) {
    --cui-table-of-contents-background: var(--card);
    --cui-table-of-contents-border-color: var(--border);
    --cui-table-of-contents-border-width: 1px;
    --cui-table-of-contents-radius: var(--radius-panel);
    --cui-table-of-contents-shadow: var(--shadow-sm);
    --cui-table-of-contents-backdrop-filter: none;
    --cui-table-of-contents-padding: calc(var(--spacing) * 4);
    --cui-table-of-contents-label-foreground: var(--muted-foreground);
    --cui-table-of-contents-label-font-size: var(--text-caption);
    --cui-table-of-contents-label-font-weight: var(--font-weight-medium);
    --cui-table-of-contents-label-gap: calc(var(--spacing) * 3);
    --cui-table-of-contents-item-foreground: var(--muted-foreground);
    --cui-table-of-contents-item-hover-foreground: var(--foreground);
    --cui-table-of-contents-item-active-foreground: var(--foreground);
    --cui-table-of-contents-item-font-size: var(--text-body);
    --cui-table-of-contents-item-line-height: var(--leading-normal);
    --cui-table-of-contents-item-font-weight: var(--font-weight-normal);
    --cui-table-of-contents-item-root-font-weight: var(--font-weight-medium);
    --cui-table-of-contents-item-padding-block: calc(var(--spacing) * 1.5);
    --cui-table-of-contents-item-padding-inline: calc(var(--spacing) * 3);
    --cui-table-of-contents-item-indent: calc(var(--spacing) * 2);
    --cui-table-of-contents-rail-background: var(--border);
    --cui-table-of-contents-rail-width: 1px;
    --cui-table-of-contents-trail-background: var(--foreground);
    --cui-table-of-contents-trail-width: 2px;
    --cui-table-of-contents-trail-radius: var(--cui-table-of-contents-trail-width);
    --cui-table-of-contents-highlight-radius: var(--radius-popup-item);
    --cui-table-of-contents-highlight-background: var(--active-fill);
    border: var(--cui-table-of-contents-border-width) solid var(--cui-table-of-contents-border-color);
    border-radius: var(--cui-table-of-contents-radius);
    background-color: var(--cui-table-of-contents-background);
    box-shadow: var(--cui-table-of-contents-shadow);
    -webkit-backdrop-filter: var(--cui-table-of-contents-backdrop-filter);
    backdrop-filter: var(--cui-table-of-contents-backdrop-filter);
    padding: var(--cui-table-of-contents-padding);
    font-size: var(--cui-table-of-contents-item-font-size);
    line-height: var(--cui-table-of-contents-item-line-height);
  }

  :where([data-control-family="table-of-contents"][data-slot="label"]) {
    margin-block-end: var(--cui-table-of-contents-label-gap);
    color: var(--cui-table-of-contents-label-foreground);
    font-size: var(--cui-table-of-contents-label-font-size);
    font-weight: var(--cui-table-of-contents-label-font-weight);
  }

  :where([data-control-family="table-of-contents"][data-slot="rail"]) {
    inline-size: var(--cui-table-of-contents-rail-width);
    background-color: var(--cui-table-of-contents-rail-background);
  }

  :where([data-control-family="table-of-contents"][data-slot="item"]) {
    padding-block: var(--cui-table-of-contents-item-padding-block);
    padding-inline: var(--cui-table-of-contents-item-padding-inline);
    padding-inline-start: calc(
      var(--cui-table-of-contents-item-padding-inline) +
      var(--_toc-depth) *
      var(--cui-table-of-contents-item-indent)
    );
    color: var(--cui-table-of-contents-item-foreground);
    font-size: var(--cui-table-of-contents-item-font-size);
    font-weight: var(--cui-table-of-contents-item-font-weight);
    line-height: var(--cui-table-of-contents-item-line-height);
    overflow-wrap: anywhere;
  }

  :where([data-control-family="table-of-contents"][data-slot="item"][data-depth="0"]) {
    font-weight: var(--cui-table-of-contents-item-root-font-weight);
  }

  @media (hover: hover) {
    :where([data-control-family="table-of-contents"][data-slot="item"]:hover) {
      color: var(--cui-table-of-contents-item-hover-foreground);
    }
  }

  :where([data-control-family="table-of-contents"][data-slot="item"]:focus-visible) {
    color: var(--cui-table-of-contents-item-hover-foreground);
  }

  :where([data-control-family="table-of-contents"][data-slot="item"][data-active]) {
    color: var(--cui-table-of-contents-item-active-foreground);
  }

  :where([data-control-family="table-of-contents"][data-slot="root"] [data-control-family="track-highlight"][data-slot="root"]) {
    --cui-track-highlight-transition-duration: var(--duration-base);
    --cui-track-highlight-radius: var(--cui-table-of-contents-highlight-radius);
    --cui-track-highlight-background: var(--cui-table-of-contents-highlight-background);
    --cui-track-highlight-ring-color: transparent;
    --cui-track-highlight-shadow: none;
  }

  :where([data-control-family="table-of-contents"][data-slot="root"][data-variant="trail"]) {
    --cui-table-of-contents-highlight-radius: 0px;
    --cui-table-of-contents-highlight-background: transparent;
  }

  :where([data-control-family="table-of-contents"][data-slot="trail"]) {
    inline-size: var(--cui-table-of-contents-trail-width);
    border-radius: var(--cui-table-of-contents-trail-radius);
    background-color: var(--cui-table-of-contents-trail-background);
  }
}

